action.mutation:
mutation Mutation($supplierPayload: [SupplierCreatePayloadInput!]!, 
  	$supplierAddressPayload: [SupplierAddressCreatePayloadInput!]!, 
  	$facilityPayload: [FacilityCreatePayloadInput!]!,
		$workcenterPayload: [WorkcenterCreatePayloadInput!]!) {
  createSupplier(payload: $supplierPayload) {
    id	
  }

  createSupplierAddress(payload: $supplierAddressPayload) {
    id	
  }

  createFacility(payload: $facilityPayload) {
    id	
  }

  createWorkcenter(payload: $workcenterPayload) {
    id	
  }
}

transforms.pre:
$components.OspFom.data.(


  $isOutsideProcessor := $components.Form1.data.supplierType.id = "Outside Processor";
  $supplierTypeId := $components.Form1.data.supplierType.id;
  $noAddress := $not($exists(supplierAddressFields));
  $supplierId := $cuid();
  $facilityId := $cuid();
  $supplierAddressId := $cuid();

  $isOutsideProcessor and $noAddress ? $throw("Error no address provided.") : {
    "supplierPayload": {
      "create": {
        "code": code,
        "name": name,
        "supplierStatusId": supplierStatusId.id,
        "supplierTypeId": $supplierTypeId,
        "active": active,
        "externalId": externalId,
        "id": $supplierId
      }
    },
    "supplierAddressPayload": $exists(supplierAddressFields) ? {
    "create": {
        "id": $supplierAddressId,
        "code": supplierAddrCode,
        "shipTo": shipTo,
        "main": main,
        "plantIdentifier": supplierPlantId,
        "address": supplierAddressFields,
        "supplierId": $supplierId,
        "active": active
      }
      } : [],
     "facilityPayload": $isOutsideProcessor ? {
      "create": {
        "id": $facilityId,
        "supplierAddressId": $supplierAddressId,
        "code": code,
        "name": name,
        "typeId": "Outside"

      }
    } : [],
    "workcenterPayload": $isOutsideProcessor ? {
      "create": {
        "code": code,
        "name": name,
        "supplierId": $supplierId,
        "concurrency": 999999,
        "workcenterTypeId": "Outside Processor",
        "shiftGroupId": "Default",
        "modeGroupId": "Default",
        "facilityId":$facilityId
      }
    } : []
  }
)
